using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Linq;

namespace DTBK.Engine.Estimation;

public enum GuiValueKind { Input, Derived, Lookup, Formula, Reference, DisplayOnly }
public enum GuiControlKind { TextBox, NumericBox, ComboBox, CheckBox, DatePicker, Button, DataGrid, SubTable, FormulaBar, FilterBox, Tree, VerticalScrollBar, HorizontalScrollBar, Tab, Splitter, StatusBar }
public sealed record GuiCellBinding(string SheetId, string TableId, string ColumnId, string DomainPath, GuiValueKind ValueKind, string Source, string Formula, IReadOnlyList<string> Dependencies, string InvalidationScope, GuiControlKind ControlKind = GuiControlKind.DataGrid, bool Editable = false);
public sealed record GuiTableBinding(string SheetId, string TableId, string Purpose, string RowKey, IReadOnlyList<string> Columns, string PrimarySource, IReadOnlyList<string> SubTables, IReadOnlyList<string> Commands, string RecalculationScope);
public sealed record GuiControlBinding(string ControlId, string SheetId, GuiControlKind Kind, string Region, string Workflow, string Command, string DataSource, string Output, bool Required, bool Implemented);
public sealed class GuiDataSourceContract
{
 public IReadOnlyList<GuiTableBinding> Tables { get; } public IReadOnlyList<GuiCellBinding> Cells { get; } public IReadOnlyList<GuiControlBinding> Controls { get; }
 public GuiDataSourceContract(IEnumerable<GuiTableBinding> tables,IEnumerable<GuiCellBinding> cells,IEnumerable<GuiControlBinding> controls){Tables=new ReadOnlyCollection<GuiTableBinding>(tables.ToList());Cells=new ReadOnlyCollection<GuiCellBinding>(cells.ToList());Controls=new ReadOnlyCollection<GuiControlBinding>(controls.ToList());}
 public GuiCellBinding ResolveCell(string s,string t,string c)=>Cells.Single(x=>x.SheetId==s&&x.TableId==t&&x.ColumnId==c); public IEnumerable<GuiCellBinding> ForSheet(string s)=>Cells.Where(x=>x.SheetId==s); public IEnumerable<GuiControlBinding> RequiredMissingControls()=>Controls.Where(x=>x.Required&&!x.Implemented);
}
