 private static void AddSheet(List<GuiTableBinding> t,List<GuiCellBinding> c,string id,string name,string table,string purpose,string rowKey,string[] cols,string source,string[] subs,string[] cmds){t.Add(new GuiTableBinding(id,table,purpose,rowKey,cols,source,subs,cmds,"DependencyGraph → affected projections → CalculationState"));foreach(var col in cols){var e=col is "Quantity" or "NormCode" or "GroupId" or "Adjustment" or "Note" or "Reason" or "Status";var k=e?GuiValueKind.Input:GuiValueKind.Reference;c.Add(new GuiCellBinding(id,table,col,$"{table}.{col}",k,source,e?"":$"[{col}]",e?new[]{$"{table}.{col}"}:Array.Empty<string>(),"Row+Table+DependentSheets",e?GuiControlKind.TextBox:GuiControlKind.DataGrid,e));}}
 private static void AddCoreControls(List<GuiControlBinding> c){c.Add(new("GUI-CMD-RECALCULATE","GLOBAL",GuiControlKind.Button,"Calculation","Calculate","CalculateEstimate","CalculationRequest → CalculationStateEngine.Calculate()","CalculationState + projections",true,true));c.Add(new("GUI-CMD-RECALCULATE-AFFECTED","GLOBAL",GuiControlKind.Button,"Calculation","RecalculateAffected","RecalculateAffected","DependencyGraph + RecalculationScheduler","Affected projections",true,false));c.Add(new("GUI-CMD-FORMULA-BAR","S05",GuiControlKind.FormulaBar,"Grid header","Edit formula / inspect formula","FormulaEditor","SelectedCell.Formula","FormulaTrace + dependency graph",true,false));c.Add(new("GUI-CMD-SOURCE-INSPECTOR","S08",GuiControlKind.Button,"Audit","Source inspector","InspectSource","CellBinding.Source","Source/provenance panel",true,false));c.Add(new("GUI-CMD-GOTO-CELL","S08",GuiControlKind.Button,"Audit","Go to cell","GoToCell","Sheet/Table/Row/Column","Selected GUI cell",true,false));c.Add(new("GUI-CMD-UNDO","GLOBAL",GuiControlKind.Button,"Document","Undo","Undo","RevisionState","Previous state",true,false));c.Add(new("GUI-CMD-REDO","GLOBAL",GuiControlKind.Button,"Document","Redo","Redo","RevisionState","Next state",true,false));c.Add(new("GUI-CMD-FILTER","S05",GuiControlKind.FilterBox,"Grid header","Filter rows","Filter","Current table query","Filtered projection",true,false));c.Add(new("GUI-SCROLL-V","ALL",GuiControlKind.VerticalScrollBar,"Each grid","Vertical scrolling","Scroll","Viewport only","Viewport",true,true));c.Add(new("GUI-SCROLL-H","ALL",GuiControlKind.HorizontalScrollBar,"Each grid","Horizontal scrolling","Scroll","Viewport only","Viewport",true,true));c.Add(new("GUI-SUBTABLE-EXPAND","ALL",GuiControlKind.SubTable,"Grid row","Expand detail","ExpandDetail","RowKey","Detail projection",true,false));c.Add(new("GUI-SHEET-NAV","GLOBAL",GuiControlKind.Tab,"Bottom workbook strip","Navigate sheets","SelectSheet","SheetId","Workspace",true,true));c.Add(new("GUI-SPLITTER","ALL",GuiControlKind.Splitter,"Main workspace","Resize main/subtable","Resize","LayoutState","Viewport layout",true,true));c.Add(new("GUI-STATUS","GLOBAL",GuiControlKind.StatusBar,"Bottom status","State/version/provenance","ShowStatus","CalculationState.Version","Status bar",true,false));}
